estados &lt;- Arqueo.RAIS.2022_2025 %&gt;% 
dplyr::filter(Ind.Vínculo.Ativo.31.12=="SIM") %&gt;% 
group_by(Ano, UF.Estabelecimento) %&gt;% 
  summarise(quant.uf= n(), .groups = "drop") |&gt; 
  mutate(Ano = as.factor(Ano))

grafico &lt;- estados |&gt;
