  e_charts(Ano) |&gt;
  e_bar(quant.uf) |&gt;
  e_facet(rows = 4, cols = 6, legend_pos = "bottom", legend_space = 12) |&gt;
  e_tooltip(
    extraCssText = "text-align: left;",
    trigger = "axis",
    formatter = htmlwidgets::JS("
      function(params) {
        var ano = params[0].axisValue;
        var result = 'Ano: ' + ano + '&lt;br/&gt;';
        params.forEach(function(p) {
          result += p.marker + ' ' + p.seriesName + ': ' + p.value[1] + '&lt;br/&gt;';
        });
        return result;
      }
    ")
  )

