5.3 Remuneração Média
A variável Vl.Rem.Média.Nom armazena a média das remunerações mensais recebidas pelo trabalhador ao longo do ano-base. Com esse dado, é possível visualizar a distribuição dos valores da média nominal na forma de boxplot, uma representação visual das medidas de posição e ideal para realizar comparações rápidas nos registros para identificar simetria/assimetria, dispersão e valores discrepantes/atípicos (outliers).


Mostrar código executado
tabela &lt;- remunera_corrigido %&gt;%
  group_by(Ano) %&gt;%
  dplyr::filter(Vl.Rem.Média.Nom &gt; 0) |&gt; 
  summarise(
    Mínimo = min(Vl.Rem.Média.Nom, na.rm = TRUE),
    Q1 = quantile(Vl.Rem.Média.Nom, 0.25, na.rm = TRUE),
    Mediana = median(Vl.Rem.Média.Nom, na.rm = TRUE),
    Q3 = quantile(Vl.Rem.Média.Nom, 0.75, na.rm = TRUE),
    Máximo = max(Vl.Rem.Média.Nom, na.rm = TRUE)
  ) %&gt;%
  mutate(across(where(is.numeric), ~ round(., 2))) %&gt;%
  mutate(Ano = as.character(Ano))  # chave para o objeto JS

tabela_list &lt;- list()
for(i in 1:nrow(tabela)) {
  ano &lt;- tabela$Ano[i]
  tabela_list[[ano]] &lt;- list(
    Minimo = tabela$Mínimo[i],
    Q1 = tabela$Q1[i],
    Mediana = tabela$Mediana[i],
    Q3 = tabela$Q3[i],
    Maximo = tabela$Máximo[i]
  )
}

tabela_json &lt;- toJSON(tabela_list, auto_unbox = TRUE)

dados_boxplot &lt;- remunera_corrigido %&gt;%
  dplyr::filter(Vl.Rem.Média.Nom &gt; 0) %&gt;%
  mutate(Ano = factor(Ano, levels = c(2022, 2023, 2024, 2025)))

tooltip_js &lt;- sprintf("
  function(params) {
    // Função auxiliar de formatação monetária
    var formatMoney = function(val) {
      if (typeof val !== 'number') val = parseFloat(val);
      return 'R$ ' + val.toFixed(2)
        .replace('.', ',')
        .replace(/(\\d)(?=(\\d{3})+(?!\\d))/g, '$1.');
    };

    // Dados da tabela
    var tabela = %s;

    // Identificar o ano
    var ano = params.name || params.axisValue;

    // Verificar se é uma caixa (array com 5 elementos)
    if (params.value && Array.isArray(params.value) && params.value.length &gt;= 5) {
      // Buscar estatísticas da tabela para este ano
      var stats = tabela[ano];
      if (stats) {
        return 'Ano: ' + ano + '&lt;br/&gt;' +
               'Mínimo: ' + formatMoney(stats.Minimo) + '&lt;br/&gt;' +
               '1º Quartil: ' + formatMoney(stats.Q1) + '&lt;br/&gt;' +
               'Mediana: ' + formatMoney(stats.Mediana) + '&lt;br/&gt;' +
               '3º Quartil: ' + formatMoney(stats.Q3) + '&lt;br/&gt;' +
               'Máximo: ' + formatMoney(stats.Maximo);
      } else {
        return 'Ano: ' + ano + ' (dados não encontrados)';
      }
    } else {
      // É um outlier
      var outlierVal = params.value;
      if (Array.isArray(outlierVal)) outlierVal = outlierVal[1];
      return 'Ano: ' + ano + '&lt;br/&gt;' +
             'Outlier: ' + formatMoney(outlierVal);
    }
  }
", tabela_json)

dados_boxplot %&gt;%
  group_by(Ano) %&gt;%
  e_charts(Ano) %&gt;%
  e_boxplot(Vl.Rem.Média.Nom) %&gt;%
  e_y_axis(
    axisLabel = list(
      fontSize = 10,
      formatter = htmlwidgets::JS("
        function(value) {
          return 'R$ ' + value.toFixed(2)
            .replace('.', ',')
            .replace(/(\\d)(?=(\\d{3})+(?!\\d))/g, '$1.');
        }
      ")
    ),
    axisLine = list(show = TRUE),
    splitLine = list(show = TRUE)
  ) %&gt;%
  e_x_axis(
    type = "category",
    axisLabel = list(fontSize = 11),
    data = levels(dados_boxplot$Ano)
  ) %&gt;%
  e_title(
    text = "Mercado de Trabalho Formal de Arqueólogos - RAIS 2022 a 2025",
    subtext = "Boxplot da Remuneração Média dos Vínculos Ativos",
    left = "center",
    textStyle = list(fontSize = 15, fontWeight = "bold"),
    subtextStyle = list(fontSize = 12, fontWeight = "bold")
  ) %&gt;%
  e_legend(show = FALSE) %&gt;%
  e_grid(containLabel = TRUE, left = "10%", right = "10%") %&gt;%
  e_tooltip(
    extraCssText = "text-align: left;",
    trigger = "item",
    formatter = htmlwidgets::JS(tooltip_js),
    axisPointer = list(
      type = "cross",
      label = list(
        formatter = htmlwidgets::JS("
          function(params) {
            var val = parseFloat(params.value);
            if (params.axisDimension === 'y' && !isNaN(val)) {
              return 'R$ ' + val.toFixed(2)
                .replace('.', ',')
                .replace(/(\\d)(?=(\\d{3})+(?!\\d))/g, '$1.');
            } else {
              return params.value; // eixo x (ano) sem formatação
            }
          }
        ")
      )
    )
